typedef unsigned int color32;

class FEMenuEntry {};

class TextString
{
public:
	virtual color32 GetColor();
	color32 color;
};

struct FEManager
{
	char padding[0x15630];
	color32 col_unselected;
};

struct BFE_Location
{
	int levels[3];
	int beaches[3];
	bool all_levels_locked;
	bool all_beaches_locked;
	bool no_existing_levels;
};

struct MapData
{
	struct Beach
	{
		bool desc_at_right;
		char padding[11];
	} beaches[1];
	char padding[20];
};

class VOEngine
{
public:
	void setCurrentLevel(int level);
};

extern VOEngine VoiceOvers;
asm(".equ VoiceOvers, 0x0042F590");
asm(".equ setCurrentLevel__8VOEnginei, 0x00258558");

class BeachFrontEnd
{
	char padding0[0x4c];
	FEMenuEntry *highlighted;
	char padding1[0x24];
	void *menu_vtable;
	char padding2[0xc4];
	FEManager *manager;
	char padding3[0x46c];
	BFE_Location locations[1];
	char padding4[0x240];
	int current_beach_index;
	int current_level_index;
	int current_location_index;
	char padding5[0x14];
	int on_challenge;
	FEMenuEntry *chall_text[3];
	TextString *goals_completed[3];
	char padding6[0x48];
	FEMenuEntry *fe_return;
	char padding7[0x64c];
	MapData map;
	int no_progress_path;
	int in_frontend;
	int in_career_mode;

	static const int chall_y = 75;

	void SetSecondaryCursor(FEMenuEntry *entry, bool anim = true)
	{
		char *table = *(char **)((char *)this + 0x74);
		short adjustment = *(short *)(table + 0x1a8);
		typedef void (*Call)(void *, FEMenuEntry *, bool);
		((Call)*(void **)(table + 0x1ac))((char *)this + adjustment, entry, anim);
	}

	int UpdateChallenges(int cn, int offset, bool right);
	int UpdateGoals(int cn, int offset, bool right);
	void TurnBox(int b_num, bool all_off, float offset);

public:
	void SetOnChallenge(int chall);
};

asm(".equ UpdateChallenges__13BeachFrontEndiib, 0x00191CD8");
asm(".equ UpdateGoals__13BeachFrontEndiib, 0x001922F0");
asm(".equ TurnBox__13BeachFrontEndibf, 0x001926E0");

#define MAX_BEACHES_PER_LOC 3

void BeachFrontEnd::SetOnChallenge(int chall)
{
	// update flashing of goals_completed text
	if(
		in_career_mode 
//	Save/load no longer part of map screen.  (dc 07/01/02)
//		&& highlighted != save_load 
		&& highlighted != fe_return
	)
		goals_completed[on_challenge]->color = manager->col_unselected;

	on_challenge = chall;
	SetSecondaryCursor(chall_text[chall]);
	current_level_index = locations[current_location_index].levels[on_challenge];
	VoiceOvers.setCurrentLevel(current_level_index);

	float offset = chall_y;
	for(int i=0; i<MAX_BEACHES_PER_LOC; i++)
		offset = UpdateChallenges(i, offset, map.beaches[current_beach_index].desc_at_right);
	offset = UpdateGoals(on_challenge, offset, map.beaches[current_beach_index].desc_at_right);

	TurnBox(current_beach_index, false, offset);

	// update flashing of goals_completed text
	if(
		in_career_mode 
//	Save/load no longer part of map screen.  (dc 07/01/02)
//		&& highlighted != save_load 
		&& highlighted != fe_return
	)
		goals_completed[on_challenge]->color = chall_text[on_challenge]->GetColor();
}
